{"implementation": "def solve(case):
    if 'nodes' not in case or 'core_distance' not in case or 'distances' not in case:
        return {"error": "missing required fields"}
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']
    n = len(nodes)
    idx = {node: i for i, node in enumerate(nodes)}
    edges = []
    for a, b, d in dists:
        mr = max(core[a], core[b], d)
        if a > b:
            a, b = b, a
        edges.append((mr, a, b))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    selected = []
    total = 0.0
    for mr, a, b in edges:
        if union(idx[a], idx[b]):
            selected.append([a, b, mr])
            total += mr
            if len(selected) == n - 1:
                break
    if len(selected) != n - 1:
        return {"edges": [], "total_weight": 0.0, "error": "disconnected"}
    return {"edges": selected, "total_weight": total}
